import { expect, it } from 'vitest';
import { clamp } from '../src/clamp';
it('clamps at both boundaries', () => {
  expect(clamp(-2, 0, 10)).toBe(0);
  expect(clamp(20, 0, 10)).toBe(10);
  expect(clamp(5, 0, 10)).toBe(5);
});
